/**
 * Peta status & jenis Perbaikan Absen → warna, plus format tanggal untuk kartu.
 *
 * Nama status mengikuti state Workflow "Persetujuan Perbaikan Absen" persis, dan
 * warnanya disamakan dengan indikator di desk supaya orang yang bolak-balik
 * antara portal dan desk melihat isyarat yang sama:
 *   Belum Perbaikan amber  ·  Menunggu Approval Atasan/Ketua oranye
 *   Approved hijau  ·  Rejected merah  ·  Kedaluwarsa & Tidak Diputuskan abu
 *
 * Kedaluwarsa dan Tidak Diputuskan sengaja seragam abu: keduanya sama-sama
 * berakhir tanpa di-approve, dan bedanya (siapa yang lalai) sudah terbaca dari
 * nama statusnya sendiri.
 */

export const BELUM_PERBAIKAN = 'Belum Perbaikan'
export const MENUNGGU_ATASAN = 'Menunggu Approval Atasan'
export const MENUNGGU_KETUA = 'Menunggu Approval Ketua'
export const APPROVED = 'Approved'
export const REJECTED = 'Rejected'

const STATUS_BADGE = {
	[BELUM_PERBAIKAN]: 'bg-ui-surface-amber-100 text-ui-ink-amber-700',
	[MENUNGGU_ATASAN]: 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	[MENUNGGU_KETUA]: 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	[APPROVED]: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	[REJECTED]: 'bg-ui-surface-red-100 text-ui-ink-red-700',
	Kedaluwarsa: 'bg-ui-surface-gray-200 text-ui-ink-gray-600',
	'Tidak Diputuskan': 'bg-ui-surface-gray-200 text-ui-ink-gray-600',
}

export function statusBadge(s) {
	return STATUS_BADGE[s] || 'bg-ui-surface-gray-200 text-ui-ink-gray-700'
}

// Warna teks saja (tanpa latar) — untuk info kecil di bawah status Kehadiran.
const STATUS_TEKS = {
	[BELUM_PERBAIKAN]: 'text-ui-ink-amber-700',
	[MENUNGGU_ATASAN]: 'text-ui-ink-orange-700',
	[MENUNGGU_KETUA]: 'text-ui-ink-orange-700',
	[APPROVED]: 'text-ui-ink-green-700',
	[REJECTED]: 'text-ui-ink-red-700',
}

export function statusTeks(s) {
	return STATUS_TEKS[s] || 'text-ui-ink-gray-500'
}

// Titik warna (cincin) di pilihan filter status — gaya yang sama dengan filter
// status Target dan Realisasi.
const STATUS_TITIK = {
	[BELUM_PERBAIKAN]: 'border-ui-line-amber-500',
	[MENUNGGU_ATASAN]: 'border-ui-line-orange-500',
	[MENUNGGU_KETUA]: 'border-ui-line-orange-500',
	[APPROVED]: 'border-ui-line-green-500',
	[REJECTED]: 'border-ui-line-red-500',
}

export function statusTitik(s) {
	return STATUS_TITIK[s] || 'border-ui-line-gray-400'
}

/**
 * Pilihan filter status. `label` dipendekkan untuk dua status menunggu supaya
 * muat di tombol filter; `value` tetap nama state Workflow aslinya.
 */
export const PILIHAN_STATUS = [
	{ value: '', label: 'Semua' },
	{ value: BELUM_PERBAIKAN, label: 'Belum Perbaikan' },
	{ value: MENUNGGU_ATASAN, label: 'Menunggu Atasan' },
	{ value: MENUNGGU_KETUA, label: 'Menunggu Ketua' },
	{ value: APPROVED, label: 'Approved' },
	{ value: REJECTED, label: 'Rejected' },
	{ value: 'Kedaluwarsa', label: 'Kedaluwarsa' },
	{ value: 'Tidak Diputuskan', label: 'Tidak Diputuskan' },
]

/** Label status yang dipendekkan — dipakai badge di kartu daftar. */
export function labelStatus(s) {
	return PILIHAN_STATUS.find((p) => p.value === s)?.label || s || '—'
}

